import { createServer } from 'node:http'
import { join, dirname } from 'node:path'
import { fileURLToPath } from 'node:url'
import { createStore } from './lib/store.js'

const DATA_FILE = join(dirname(fileURLToPath(import.meta.url)), 'books.json')

export function escapeHtml(s) {
  return String(s ?? '')
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;')
    .replaceAll('"', '&quot;')
    .replaceAll("'", '&#39;')
}

function page(title, body) {
  return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>${escapeHtml(title)} · My Books</title>
<style>
  body { font-family: system-ui, sans-serif; max-width: 42rem; margin: 2rem auto; padding: 0 1rem; line-height: 1.5; color: #222; }
  h1 { margin-bottom: 0.25rem; }
  a { color: #06c; }
  ul { padding-left: 1.25rem; }
  li { margin: 0.4rem 0; }
  form { margin: 1rem 0; display: grid; gap: 0.5rem; }
  label { display: grid; gap: 0.2rem; font-weight: 600; }
  input, textarea { font: inherit; padding: 0.4rem; border: 1px solid #bbb; border-radius: 4px; font-weight: 400; }
  button { font: inherit; padding: 0.4rem 0.9rem; border: 1px solid #999; border-radius: 4px; background: #f4f4f4; cursor: pointer; width: fit-content; }
  button:hover { background: #e8e8e8; }
  .finish { display: inline; margin-left: 0.5rem; }
  .finish button { padding: 0.15rem 0.5rem; font-size: 0.85rem; }
  .muted { color: #666; }
  .notes { white-space: pre-wrap; background: #f7f7f7; border: 1px solid #e2e2e2; border-radius: 4px; padding: 0.75rem; }
  section { margin-top: 2rem; }
</style>
</head>
<body>
<header><a href="/">My Books</a></header>
${body}
</body>
</html>`
}

function bookItem(book) {
  const finish = book.status === 'reading'
    ? `<form class="finish" method="post" action="/books/${book.id}/finish"><button type="submit">Mark finished</button></form>`
    : ''
  return `<li><a href="/books/${book.id}">${escapeHtml(book.title)}</a> — ${escapeHtml(book.author)}${finish}</li>`
}

function homePage(books) {
  const reading = books.filter(b => b.status === 'reading')
  const finished = books.filter(b => b.status === 'finished')

  const readingList = reading.length
    ? `<ul>${reading.map(bookItem).join('')}</ul>`
    : '<p class="muted">Nothing on the go. Add a book below.</p>'
  const finishedList = finished.length
    ? `<ul>${finished.map(bookItem).join('')}</ul>`
    : '<p class="muted">No finished books yet.</p>'

  return page('Home', `
<h1>My Books</h1>
<section>
  <h2>Currently reading</h2>
  ${readingList}
</section>
<section>
  <h2>Finished</h2>
  ${finishedList}
</section>
<section>
  <h2>Add a book</h2>
  <form method="post" action="/books">
    <label>Title <input name="title" required></label>
    <label>Author <input name="author" required></label>
    <label>Notes <textarea name="notes" rows="3"></textarea></label>
    <button type="submit">Add book</button>
  </form>
</section>`)
}

function bookPage(book) {
  return page(book.title, `
<h1>${escapeHtml(book.title)}</h1>
<p class="muted">by ${escapeHtml(book.author)} · ${book.status === 'finished' ? `finished ${book.finishedAt.slice(0, 10)}` : 'currently reading'}</p>
${book.status === 'reading' ? `<form method="post" action="/books/${book.id}/finish"><button type="submit">Mark finished</button></form>` : ''}
<h2>Notes</h2>
${book.notes ? `<div class="notes">${escapeHtml(book.notes)}</div>` : '<p class="muted">No notes yet.</p>'}
<p><a href="/">← Back to all books</a></p>`)
}

function readBody(req) {
  return new Promise((resolve, reject) => {
    let body = ''
    req.on('data', chunk => {
      body += chunk
      if (body.length > 1_000_000) req.destroy(new Error('body too large'))
    })
    req.on('end', () => resolve(new URLSearchParams(body)))
    req.on('error', reject)
  })
}

function redirect(res, location) {
  res.writeHead(303, { location })
  res.end()
}

function html(res, status, content) {
  res.writeHead(status, { 'content-type': 'text/html; charset=utf-8' })
  res.end(content)
}

export function createApp(store) {
  return createServer(async (req, res) => {
    try {
      const url = new URL(req.url, 'http://localhost')
      const path = url.pathname

      if (req.method === 'GET' && path === '/') {
        return html(res, 200, homePage(await store.list()))
      }

      if (req.method === 'POST' && path === '/books') {
        const form = await readBody(req)
        const title = (form.get('title') || '').trim()
        const author = (form.get('author') || '').trim()
        if (!title || !author) {
          return html(res, 400, page('Error', '<h1>Title and author are required</h1><p><a href="/">Back</a></p>'))
        }
        await store.add({ title, author, notes: (form.get('notes') || '').trim() })
        return redirect(res, '/')
      }

      const bookMatch = path.match(/^\/books\/([\w-]+)$/)
      if (req.method === 'GET' && bookMatch) {
        const book = await store.get(bookMatch[1])
        if (!book) return html(res, 404, page('Not found', '<h1>Book not found</h1><p><a href="/">Back</a></p>'))
        return html(res, 200, bookPage(book))
      }

      const finishMatch = path.match(/^\/books\/([\w-]+)\/finish$/)
      if (req.method === 'POST' && finishMatch) {
        const book = await store.finish(finishMatch[1])
        if (!book) return html(res, 404, page('Not found', '<h1>Book not found</h1><p><a href="/">Back</a></p>'))
        return redirect(res, `/books/${book.id}`)
      }

      html(res, 404, page('Not found', '<h1>Not found</h1><p><a href="/">Back</a></p>'))
    } catch (err) {
      console.error(err)
      html(res, 500, page('Error', '<h1>Something went wrong</h1><p><a href="/">Back</a></p>'))
    }
  })
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const port = Number(process.env.PORT) || 3000
  createApp(createStore(DATA_FILE)).listen(port, () => {
    console.log(`Listening on http://localhost:${port}`)
  })
}

