import { describe, it, expect, beforeEach, afterEach } from 'vitest'
import { mkdtemp, rm, readFile } from 'node:fs/promises'
import { tmpdir } from 'node:os'
import { join } from 'node:path'
import { createStore } from '../lib/store.js'

let dir
let store

beforeEach(async () => {
  dir = await mkdtemp(join(tmpdir(), 'books-'))
  store = createStore(join(dir, 'books.json'))
})

afterEach(async () => {
  await rm(dir, { recursive: true, force: true })
})

describe('store', () => {
  it('returns an empty list when the file does not exist', async () => {
    expect(await store.list()).toEqual([])
  })

  it('adds a book with reading status', async () => {
    const book = await store.add({ title: 'Dune', author: 'Frank Herbert', notes: 'spicy' })
    expect(book.status).toBe('reading')
    expect(book.finishedAt).toBeNull()
    expect(book.id).toBeTruthy()
    expect(await store.list()).toHaveLength(1)
  })

  it('persists books across store instances', async () => {
    await store.add({ title: 'Dune', author: 'Frank Herbert' })
    const fresh = createStore(join(dir, 'books.json'))
    expect((await fresh.list())[0].title).toBe('Dune')
  })

  it('writes valid JSON to the file', async () => {
    await store.add({ title: 'Dune', author: 'Frank Herbert' })
    const raw = JSON.parse(await readFile(join(dir, 'books.json'), 'utf8'))
    expect(raw).toHaveLength(1)
  })

