    const book = await store.add({ title: 'Dune', author: 'Frank Herbert' })
    const finished = await store.finish(book.id)
    expect(finished.status).toBe('finished')
    expect(finished.finishedAt).toBeTruthy()
    expect((await store.get(book.id)).status).toBe('finished')
  })

  it('returns null when finishing a missing book', async () => {
    expect(await store.finish('nope')).toBeNull()
  })
})

