import { describe, it, expect, beforeAll, afterAll } from 'vitest'
import { mkdtemp, rm } from 'node:fs/promises'
import { tmpdir } from 'node:os'
import { join } from 'node:path'
import { createApp, escapeHtml } from '../server.js'
import { createStore } from '../lib/store.js'

let server
let base
let dir

beforeAll(async () => {
  dir = await mkdtemp(join(tmpdir(), 'books-server-'))
  server = createApp(createStore(join(dir, 'books.json')))
  await new Promise(resolve => server.listen(0, resolve))
  base = `http://localhost:${server.address().port}`
})

afterAll(async () => {
  await new Promise(resolve => server.close(resolve))
  await rm(dir, { recursive: true, force: true })
})

async function addBook(title, author, notes = '') {
  return fetch(`${base}/books`, {
    method: 'POST',
    headers: { 'content-type': 'application/x-www-form-urlencoded' },
    body: new URLSearchParams({ title, author, notes }),
    redirect: 'manual',
  })
}

describe('server', () => {
  it('shows reading and finished sections on the home page', async () => {
    const res = await fetch(`${base}/`)
    const body = await res.text()
    expect(res.status).toBe(200)
    expect(body).toContain('Currently reading')
    expect(body).toContain('Finished')
    expect(body).toContain('Add a book')
  })

  it('adds a book and lists it as currently reading', async () => {
    const res = await addBook('Dune', 'Frank Herbert')
    expect(res.status).toBe(303)
    const body = await (await fetch(`${base}/`)).text()
    expect(body).toContain('Dune')
    expect(body).toContain('Frank Herbert')
  })

  it('rejects a book without a title or author', async () => {
    const res = await addBook('', '')
    expect(res.status).toBe(400)
  })

  it('serves a shareable page for a single book', async () => {
    await addBook('The Hobbit', 'J.R.R. Tolkien', 'second breakfast')
    const home = await (await fetch(`${base}/`)).text()
    const id = home.match(/\/books\/([\w-]+)">The Hobbit/)[1]

    const res = await fetch(`${base}/books/${id}`)
    const body = await res.text()
    expect(res.status).toBe(200)
    expect(body).toContain('The Hobbit')
    expect(body).toContain('J.R.R. Tolkien')
    expect(body).toContain('second breakfast')
  })

  it('marks a book as finished', async () => {
    await addBook('Solaris', 'Stanislaw Lem')
    let home = await (await fetch(`${base}/`)).text()
    const id = home.match(/\/books\/([\w-]+)">Solaris/)[1]

    const res = await fetch(`${base}/books/${id}/finish`, { method: 'POST', redirect: 'manual' })
    expect(res.status).toBe(303)
    expect(res.headers.get('location')).toBe(`/books/${id}`)

    home = await (await fetch(`${base}/`)).text()
    const finishedSection = home.split('<h2>Finished</h2>')[1]
    expect(finishedSection).toContain('Solaris')
    expect(home).not.toContain(`action="/books/${id}/finish"`)
  })

  it('returns 404 for unknown books and routes', async () => {
    expect((await fetch(`${base}/books/nope`)).status).toBe(404)
    expect((await fetch(`${base}/nowhere`)).status).toBe(404)
  })

  it('escapes HTML in book fields', async () => {
    await addBook('<script>alert(1)</script>', 'Eve <b>')
    const body = await (await fetch(`${base}/`)).text()
    expect(body).not.toContain('<script>alert(1)</script>')
    expect(body).toContain('&lt;script&gt;')
  })

  it('escapeHtml escapes special characters', () => {
    expect(escapeHtml(`<a href="x">&'`)).toBe('&lt;a href=&quot;x&quot;&gt;&amp;&#39;')
  })
})

